INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66297641', 66297641, 'analyze_legacy', 'Kementerian Perhubungan', 'central', 'POLITEKNIK PERKERETAAPIAN INDONESIA MADIUN', 'Pengadaan Belanja Kebutuhan Pelaksanaan Kegiatan Ketarunaan', 'Barang', 'Pengadaan Langsung', 'Jawa Timur, Madiun (Kota)', 2172152000, 'January 2026', 'APBN - RUPIAH MURNI (A), APBN - BADAN LAYANAN UMUM (F)', 1, 1, '1 Paket', 'Paket pekerjaan ini berupa pengadaan belanja kebutuhan untuk mendukung pelaksanaan kegiatan ketarunaan di Politeknik Perkeretaapian Indonesia Madiun, yang meliputi pembinaan ketahanan kampus, penerimaan peserta diklat, wisuda dan pelantikan terpadu, pelatihan dan tes TOEFL institusional, pembinaan dan pengawasan petugas jaga taruna, pertemuan rutin dengan Ikatan Alumni PPI Madiun (IKAAPI), pertukaran taruna pola pembibitan, permagangan taruna luar negeri, pemberian beasiswa, serta dukungan kegiatan taruna pada masa angkutan Natal dan Tahun Baru serta Angkutan Lebaran.', 'Pekerjaan ini meliputi penyediaan berbagai kebutuhan barang yang digunakan untuk menunjang pelaksanaan kegiatan ketarunaan sesuai dengan kebutuhan unit pelaksana kegiatan, dengan ketentuan barang yang disediakan harus dalam kondisi baru, memiliki kualitas baik, layak digunakan, serta diserahkan sesuai dengan jenis, jumlah, dan waktu yang telah ditetapkan agar kegiatan ketarunaan dapat berjalan dengan lancar dan tertib.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2680250);
