INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66336727', 66336727, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Sumatera Selatan', 'Obat Suntik KB Progestin 1ml', 'Barang', 'E-Purchasing', 'Sumatera Selatan, Palembang (Kota)', 104000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 16000, VIAL, @ 6500 )', '1. Obat Suntik KB Progestin 1ml ( 16000, VIAL, @ 6500 ); Pengadaan Alokon melalui e-catalog yang dilaksanakan oleh pengelola pengadaan barang/jasa pemerintah (PPK/PP)', 'Obat Suntik KB Progestin 1 ml (16.000 vial, Rp.104.000.000 ) Suntik KB Progestin adalah obat kontrasepsi dalam bentuk sediaan cairan injeksi yang dikemas dalam vial dan digunakan akseptor setiap 3 bulan dengan cara disuntikkan ke dalam otot (intramuskular/IM) oleh tenaga Kesehatan. B. Spesifikasi : 1) Umum : a) Kandungan Tiap vial mengandung zat aktif 150 mg Medroxyprogesterone Acetate dalam 1 ml injeksi suspense steril. b) Sertifikasi Mutu (1) Nomor Izin Edar (NIE) Mempunyai Nomor Izin Edar (NIE) dari BPOM- RI dan masih berlaku. (2) Cara Pembuatan Obat yang Baik (CPOB) Mempunyai sertifikat CPOB dari BPOM-RI dan masih berlaku . (3) Cara Distribusi Obat yang Baik (CDOB) Mempunyai sertifikat CDOB dari BPOM-RI dan masih berlaku bagi Pedagang Besar Farmasi (PBF). (4) Certificate Of Analysis (CoA) Memiliki CoA yang memenuhi syarat. a. Parameter uji : Sesuai dengan produk yang didaftarkan ke BPOM RI. b. Masa kadaluarsa: Paling sedikit 2.5 (dua koma lima) tahun sejak diterima di gudang Perwakilan BKKBN Provinsi Sumatera Selatan. 2) Khusus Kemasan Suntik KB Progestin : Informasi produk penandaan pada kemasan mengikut persyaratan dalam Nomor Ijin Edar produk obat suntik KB Progestin dari BPOM dan informasi tambahan dari BKKBN sebagai berikut : a) Individual Pack (1) Pada setiap individual pack harus tercantum nomor batch/lot, nomor registrasi, waktu produksi (bulan, tahun) dan masa kadaluarsa (tanggal, bulan, tahun). (2) Pada setiap individual pack tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (3) Pada setiap individual pack tercantum tulisan “Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna merah. (4) Ketentuan sebagaimana disebutkan pada angka (3) dikecualikan pada : a. Produk impor yang sudah beredar di Indonesia dan pengemasannya dilakukan di negara asal. b. Tidak tersedia ruang yang memadai. (5) Jumlah individual pack yang dimasukkan kedalam inner box disesuaikan dengan kemasan yang tercantum dalam NIE. b) Inner Box (box kecil) (1) Setiap inner box dilengkapi dengan 1 copy petunjuk pemakaian dalam bahasa Indonesia. (2) Pada setiap inner box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (3) Setiap inner box tertulis nomor batch/lot, nomor registrasi, waktu produksi (bulan, tahun) dan masa kadaluarsa (tanggal, bulan, tahun). (4) Pada inner box tercantum tulisan “Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna merah. (5) Jumlah inner box yang dimasukkan ke dalam outer box (box besar) disesuaikan dengan kemasan yang tercantum dalam NIE. c) Outer Box (Box Besar) (1) Pada setiap outer box tercantum nama produk yang disesuaikan dengan nama produk di dokumen izin edar. (2) Pada outer box tertulis nomor batch/lot, nomor registrasi, waktu produksi (bulan, tahun) dan masa kadaluarsa (tanggal, bulan, tahun) tertulis pada dua sisi. (3) Setiap satu outer box tercantum tulisan “Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN APBN Tahun Anggaran 2026” dengan warna hitam/biru dan “Tidak diperjualbelikan” dengan warna merah. (4) Ketebalan karton outer box menyesuaikan dengan jenis dan berat produk agar dapat terjamin keamanan, mutu, dan manfaat produk.', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2682952);
