INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66337043', 66337043, 'analyze_legacy', 'Kementerian Kependudukan dan Pembangunan Keluarga/BKKBN', 'central', 'Perwakilan BKKBN Provinsi Sumatera Selatan', 'Amoxicillin', 'Barang', 'E-Purchasing', 'Sumatera Selatan, Palembang (Kota)', 750000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 1, '( 100000, STRIP, @ 7500 )', '1. Amoxicillin ( 100000, STRIP, @ 7500 ); Pengadaan Alokon melalui e-catalog yang dilaksanakan oleh pengelola pengadaan barang/jasa pemerintah (PPK/PP)', 'Amoxicillin (100.000 strip, Rp. 750.000.000) A. Amoxicillin adalah obat antibiotik yang berisi amoxicillin trihydrate 500 mg. Berupa tablet salut selaput/kaplet salut selaput dalam kemasan strip/blister. Amoxicillin adalah obat digunakan untuk mengobati berbagai jenis infeksi bakteri. Amoxicillin akan menghambat pertumbuhan bakteri di organ paru – paru, saluran kemih, kulit, serta di bagian telinga, hidung dan tenggorokan. Antibiotik amoxicillin adalah obat yang tidak akan bekerja pada infeksi virus seperti pilek dan flu. Menggunakan antibiotik saat tidak dibutuhkan meningkatkan risiko terkena infeksi yang kebal dengan pengobatan antibiotik. B. Spesifikasi Tekhnis - Komposisi : amoxicillin trihydrate 500 mg - Kemasan : strip/blister - Setiap strip/blister berisi 10 tablet salut selaput/kaplet salut selaput C. Registrasi Amoxicillin terdaftar di Kementerian Kesehatan RI dan memiliki Nomor Ijin Edar (NIE) yang masih berlaku. D. Masa Kadaluarsa Minimal 2 (dua) tahun pada saat dilakukan penyerahan barang di gudang Perwakilan BKKBN Provinsi Sumatera Selatan. E. Pengepakan Pelabelan/penandaan kemasan mengikuti peraturan perundang-undangan yang berlaku dari Kementerian Kesehatan RI.', 0, 'med', NULL, NULL, NULL, 2, 1, 1, 1, 1, 2683486);
