INSERT INTO packages (id, source_id, schema_version, owner_name, owner_type, satker, package_name, procurement_type, procurement_method, location_raw, budget, selection_date, funding_source, is_umkm, within_country, volume, work_description, specification, potential_waste, severity, reason, is_mencurigakan, is_pemborosan, risk_score, active_tag_count, is_priority, is_flagged, mapped_region_count, inserted_order) VALUES ('66339301', 66339301, 'analyze_legacy', 'Badan Meteorologi, Klimatologi Dan Geofisika', 'central', 'SEKRETARIAT UTAMA BMKG', 'Renewal lisensi Platform SSO', 'Jasa Lainnya', 'Pengadaan Langsung', 'DKI Jakarta, Jakarta Pusat (Kota)', 100000000, 'March 2026', 'APBN - RUPIAH MURNI (A)', 1, 0, '5 LISEN', 'Dalam melaksanakan tugas operasional maupun kegiatan dukungan manajemen, BMKG memanfaatkan berbagai aplikasi yang masing-masing memiliki sistem manajemen akses sendiri. Platform Single Sign-On (SSO) BMKG memungkinkan penggunaan berbagai aplikasi melalui satu kali akses login. Login dilakukan melalui portal khusus SSO di mana dalam pengembangan dan operasionalnya membutuhkan beberapa dukungan renewal lisensi platform antara lain sebagai berikut: 1. WhatsApp Cloud API Pro 2. Sertifikat SSL Wildcard OV 3. WordPress.com Creator 4. UptimeRobot Team 5. ChatGPT Team', 'Dalam melaksanakan tugas operasional maupun kegiatan dukungan manajemen, BMKG memanfaatkan berbagai aplikasi yang masing-masing memiliki sistem manajemen akses sendiri. Platform Single Sign-On (SSO) BMKG memungkinkan penggunaan berbagai aplikasi melalui satu kali akses login. Login dilakukan melalui portal khusus SSO di mana dalam pengembangan dan operasionalnya membutuhkan beberapa dukungan renewal lisensi platform antara lain sebagai berikut: 1. WhatsApp Cloud API Pro 2. Sertifikat SSL Wildcard OV 3. WordPress.com Creator 4. UptimeRobot Team 5. ChatGPT Team', 0, 'low', NULL, NULL, NULL, 1, 0, 0, 0, 1, 2688620);
